function calculateKillerStunChance(killerAchievementLevel, hasActiveLicense) {
	if (!hasActiveLicense) return {
		canStun: false,
		stunChance: 0,
		stunDurationMs: 0
	};
	return {
		canStun: true,
		stunChance: 50 + Math.max(0, Math.min(5, Number(killerAchievementLevel) || 0)) * 5,
		stunDurationMs: 3e3
	};
}
function getKillerAchievementInfo(rawPvpKills) {
	const kills = Math.max(0, Math.floor(Number(rawPvpKills) || 0));
	let currentLevel = 0;
	let currentTier = null;
	for (const tier of KILLER_ACHIEVEMENT_LEVELS) if (kills >= tier.requiredKills) {
		currentLevel = tier.level;
		currentTier = tier;
	}
	const nextTier = KILLER_ACHIEVEMENT_LEVELS.find((t) => t.level === currentLevel + 1) || null;
	const totalHpBonus = currentLevel * 100;
	const totalStunBonus = currentLevel * 5;
	const stunChanceWithLicense = 50 + totalStunBonus;
	const prevTarget = currentTier ? currentTier.requiredKills : 0;
	const nextTargetKills = nextTier ? nextTier.requiredKills : 500;
	const nextKillsRequired = nextTargetKills;
	const isMaxLevel = currentLevel >= 5;
	const killsRemainingForNext = Math.max(0, nextKillsRequired - kills);
	let progressPct = 100;
	if (nextTier) {
		const span = Math.max(1, nextTier.requiredKills - prevTarget);
		const done = Math.max(0, kills - prevTarget);
		progressPct = Math.max(0, Math.min(100, Math.round(done / span * 100)));
	}
	return {
		kills,
		level: currentLevel,
		maxLevel: 5,
		isMaxLevel,
		totalHpBonus,
		totalStunBonus,
		stunChanceWithLicense,
		currentTier,
		nextTier,
		nextTargetKills,
		nextKillsRequired,
		killsRemainingForNext,
		progressPct
	};
}
function formatLicenseRemainingTime(untilMs, nowMs = Date.now()) {
	const rem = Math.max(0, Number(untilMs || 0) - nowMs);
	if (rem <= 0) return "Истекла";
	const totalSec = Math.ceil(rem / 1e3);
	const days = Math.floor(totalSec / 86400);
	const hours = Math.floor(totalSec % 86400 / 3600);
	const mins = Math.floor(totalSec % 3600 / 60);
	const secs = totalSec % 60;
	const pad = (n) => String(n).padStart(2, "0");
	if (days > 0) return `${days}д ${pad(hours)}ч ${pad(mins)}м`;
	return `${pad(hours)}ч ${pad(mins)}м ${pad(secs)}с`;
}
