function getPlayerClan(nick, clanId) {
	loadFromLocal();
	if (clanId) {
		const byId = inMemoryClans.find((c) => c.id === clanId);
		if (byId) {
			if (nick) {
				const lower = nick.trim().toLowerCase();
				if (!byId.members.some((m) => m.nick.trim().toLowerCase() === lower)) {
					byId.members.push({
						nick: nick.trim(),
						role: byId.leaderNick.trim().toLowerCase() === lower ? "leader" : "warrior",
						lvl: 1,
						avatar: "🧙‍♂️",
						joinedAt: Date.now(),
						contributionExp: 0,
						contributionInfluence: 0,
						isOnline: true,
						lastSeen: Date.now()
					});
					saveToLocal();
				}
			}
			return byId;
		}
	}
	if (nick) {
		const lower = nick.trim().toLowerCase();
		const byMember = inMemoryClans.find((c) => c.members.some((m) => m.nick.trim().toLowerCase() === lower) || c.leaderNick.trim().toLowerCase() === lower);
		if (byMember) return byMember;
	}
}
