function addClanExp(clanId, expAmount, contributorNick) {
	initClanStorage();
	const clan = inMemoryClans.find((c) => c.id === clanId);
	if (!clan || expAmount <= 0) return {
		clan,
		leveledUp: false,
		newLevel: clan?.level || 1
	};
	const add = Math.max(0, Math.floor(expAmount));
	clan.level = Math.max(1, Math.min(20, Number(clan.level) || 1));
	clan.exp = Math.max(0, Math.floor(Number(clan.exp) || 0)) + add;
	let leveledUp = false;
	while (clan.level < 20) {
		const needed = getClanExpForNextLevel(clan.level);
		if (needed > 0 && clan.exp >= needed) {
			clan.exp -= needed;
			clan.level += 1;
			leveledUp = true;
		} else break;
	}
	if (clan.level >= 20) clan.level = 20;
	if (contributorNick) {
		const m = clan.members.find((mem) => mem.nick.trim().toLowerCase() === contributorNick.trim().toLowerCase());
		if (m) m.contributionExp = (m.contributionExp || 0) + add;
	}
	saveClansToSupabase();
	return {
		clan,
		leveledUp,
		newLevel: clan.level
	};
}
