function getHeroAchievementMetricValue(metric, hero) {
	if (!hero) return 0;
	switch (metric) {
		case "total_gold": return Math.max(0, Math.floor(Number(hero.totalGoldCollected || 0)), Math.floor(Number(hero.gold || 0)));
		case "mobs_killed": return Math.max(0, Math.floor(Number(hero.mobsKilled ?? hero.mobKills ?? 0)), Math.floor(Number(hero.npcCompanion?.mobsKilled || 0)));
		case "bosses_killed": {
			const explicitBosses = Math.max(0, Math.floor(Number(hero.bossesKilled || 0)));
			const maxTier = Math.max(1, Number(hero.homePyramidTier || hero.pyramidTier || 1));
			return Math.max(explicitBosses, maxTier > 1 ? maxTier - 1 : 0);
		}
		case "hero_level": return Math.max(1, Math.floor(Number(hero.level || hero.lvl || 1)));
		case "pyramid_tier": return Math.max(1, Math.floor(Number(hero.homePyramidTier || hero.pyramidTier || 1)));
		case "pvp_kills": return Math.max(0, Math.floor(Number(hero.pvpKills || 0)), Math.floor(Number(hero.pvpWins || 0)));
		case "items_sold": {
			const explicitSold = Math.max(0, Math.floor(Number(hero.itemsSold || 0)));
			const estimatedFromSellExp = Math.floor(Number(hero.sellExperience || 0) / 3);
			return Math.max(explicitSold, estimatedFromSellExp);
		}
		case "gambling_games": {
			const explicitGames = Math.max(0, Math.floor(Number(hero.gamblingGamesPlayed || 0)));
			const hasGamblingHistory = Number(hero.gamblingSpentGold || 0) > 0 || Number(hero.gamblingSpentCrystals || 0) > 0;
			return Math.max(explicitGames, hasGamblingHistory ? 1 : 0);
		}
		default: return 0;
	}
}
function evaluatePlayerAchievements(hero) {
	const claimedSet = new Set(Array.isArray(hero?.claimedAchievementIds) ? hero.claimedAchievementIds : []);
	let completedCount = 0;
	let claimedCount = 0;
	let claimableCount = 0;
	let totalClaimableCrystals = 0;
	let earnedCrystalsTotal = 0;
	let maxPossibleCrystals = 0;
	const items = PLAYER_ACHIEVEMENTS.map((tpl) => {
		const rawProgress = getHeroAchievementMetricValue(tpl.metric, hero);
		const progress = Math.max(0, rawProgress);
		const isCompleted = progress >= tpl.target;
		const isClaimed = claimedSet.has(tpl.id);
		const canClaim = isCompleted && !isClaimed;
		const pct = Math.max(0, Math.min(100, Math.round(Math.min(progress, tpl.target) / tpl.target * 100)));
		const remaining = Math.max(0, tpl.target - progress);
		maxPossibleCrystals += tpl.rewardCrystals;
		if (isCompleted) completedCount += 1;
		if (isClaimed) {
			claimedCount += 1;
			earnedCrystalsTotal += tpl.rewardCrystals;
		}
		if (canClaim) {
			claimableCount += 1;
			totalClaimableCrystals += tpl.rewardCrystals;
		}
		return {
			...tpl,
			progress,
			pct,
			isCompleted,
			isClaimed,
			canClaim,
			remaining
		};
	});
	return {
		items,
		totalCount: items.length,
		completedCount,
		claimedCount,
		claimableCount,
		totalClaimableCrystals,
		earnedCrystalsTotal,
		maxPossibleCrystals
	};
}
