						minLevel: p.minLevel !== void 0 ? Math.max(1, Number(p.minLevel)) : p.type === "npc" ? 15 : 1,
						dropChancePct: p.dropChancePct !== void 0 ? Math.max(.01, Number(p.dropChancePct)) : void 0,
