/**
* Syncs roulette prize configuration with Supabase so admin adjustments instantly update for all players.
*/
async function syncRoulettePrizesFromSupabase() {
	try {
		const res = await fetch(`${SUPABASE_REST_URL}?name=eq.__GLOBAL_CONFIG__&select=id,name,email`, { headers: {
			apikey: SUPABASE_KEY,
			Authorization: `Bearer ${SUPABASE_KEY}`
		} });
		if (res.ok) {
			const rows = await res.json();
			if (Array.isArray(rows) && rows.length > 0 && rows[0].email) try {
				const cfg = JSON.parse(rows[0].email);
				if (Array.isArray(cfg.roulettePrizes) && cfg.roulettePrizes.length > 0) {
					setMemoryRoulettePrizes(cfg.roulettePrizes);
					return cfg.roulettePrizes;
				}
			} catch (e) {}
		}
	} catch (err) {
		console.warn("Failed to sync roulette prizes from Supabase:", err);
	}
	return getRoulettePrizes();
}
async function saveRoulettePrizesToSupabase(prizes) {
	setMemoryRoulettePrizes(prizes);
	try {
		const fetchRes = await fetch(`${SUPABASE_REST_URL}?name=eq.__GLOBAL_CONFIG__&select=id,name,email`, { headers: {
			apikey: SUPABASE_KEY,
			Authorization: `Bearer ${SUPABASE_KEY}`
		} });
		let existingCfg = {};
		let configId = null;
		if (fetchRes.ok) {
			const rows = await fetchRes.json();
			if (Array.isArray(rows) && rows.length > 0) {
				configId = rows[0].id;
				try {
					existingCfg = JSON.parse(rows[0].email || "{}");
				} catch (e) {
					existingCfg = {};
				}
			}
		}
		const nextCfg = {
			...existingCfg,
			roulettePrizes: prizes,
			lastUpdated: Date.now()
		};
		const payload = {
			name: "__GLOBAL_CONFIG__",
			email: JSON.stringify(nextCfg),
			last_seen: Date.now()
		};
		if (configId) await fetch(`${SUPABASE_REST_URL}?id=eq.${configId}`, {
			method: "PATCH",
			headers: {
				apikey: SUPABASE_KEY,
				Authorization: `Bearer ${SUPABASE_KEY}`,
				"Content-Type": "application/json",
				Prefer: "return=minimal"
			},
			body: JSON.stringify(payload)
		});
		else await fetch(SUPABASE_REST_URL, {
			method: "POST",
			headers: {
				apikey: SUPABASE_KEY,
				Authorization: `Bearer ${SUPABASE_KEY}`,
				"Content-Type": "application/json",
				Prefer: "return=minimal"
			},
			body: JSON.stringify(payload)
		});
		return true;
	} catch (err) {
		console.error("Failed to save roulette prizes to Supabase:", err);
		return false;
	}
}
